import { Component, TemplateRef, computed, input } from '@angular/core';
import { NzEmptyModule } from 'ng-zorro-antd/empty';
import { TablerIconComponent, IconInbox, IconZoomExclamation, IconAlertTriangle, IconSparkles } from '@tabler/icons-angular';

/** Preset ngữ cảnh rỗng: no-data (chưa có dữ liệu) · no-results (lọc/tìm không ra) ·
 *  error (tải lỗi) · first-use (lần đầu, mời tạo mới). Đổi icon minh hoạ theo ngữ cảnh. */
export type HrmEmptyPreset = '' | 'no-data' | 'no-results' | 'error' | 'first-use';

/** hrm-empty — trạng thái rỗng, bọc nz-empty.
 *  - preset: đổi icon minh hoạ theo ngữ cảnh (không kèm text mặc định — description bên gọi cấp).
 *  - description: dòng mô tả (rỗng → dùng text mặc định đã bản địa hoá của ng-zorro).
 *  - image: TemplateRef cho hình/biểu tượng minh hoạ tuỳ biến (thắng preset).
 *  - action: TemplateRef cho nút hành động dưới mô tả (nzNotFoundFooter).
 *  Dùng: <hrm-empty preset="no-results" description="Không tìm thấy nhân viên nào" /> */
@Component({
  selector: 'hrm-empty',
  imports: [NzEmptyModule, TablerIconComponent],
  template: `
    <nz-empty
      [nzNotFoundImage]="image() ?? (presetIcon() ? presetTpl : 'default')"
      [nzNotFoundContent]="description() || undefined"
      [nzNotFoundFooter]="action() ?? undefined">
    </nz-empty>

    <ng-template #presetTpl>
      <span class="he-ic" [attr.data-preset]="preset()">
        <tabler-icon [icon]="$any(presetIcon())" [size]="40" />
      </span>
    </ng-template>
  `,
  host: { class: 'hrm-empty' },
  styles: [`
.he-ic {
  display: inline-grid; place-items: center; width: 72px; height: 72px;
  border-radius: var(--radius-full); background: var(--bg-surface-subtle); color: var(--icon-secondary);
}
.he-ic[data-preset='error'] { background: var(--error-bg); color: var(--error-base); }
.he-ic[data-preset='first-use'] { background: var(--primary-bg-subtle); color: var(--primary-base); }
  `],
})
export class HrmEmpty {
  /** Ngữ cảnh rỗng — đổi icon minh hoạ. Rỗng = hình mặc định ng-zorro. */
  readonly preset = input<HrmEmptyPreset>('');
  readonly description = input('');
  /** Hình/biểu tượng minh hoạ tuỳ biến (thắng preset). */
  readonly image = input<TemplateRef<void> | null>(null);
  /** Nút hành động hiển thị dưới mô tả (VD: "Tạo mới"). */
  readonly action = input<TemplateRef<void> | null>(null);

  protected readonly presetIcon = computed(() => {
    switch (this.preset()) {
      case 'no-data': return IconInbox;
      case 'no-results': return IconZoomExclamation;
      case 'error': return IconAlertTriangle;
      case 'first-use': return IconSparkles;
      default: return null;
    }
  });
}
